def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def first_pos(seq):
        if not seq:
            return None
        for item in seq:
            p = pos(item)
            if p is not None:
                return p
        return None

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for item in targets or []:
            p = pos(item)
            if p is None:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best_d is None or d < best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sp = pos(observation.get("self_position")) or (0, 0)
    sx, sy = sp
    op = pos(observation.get("opponent_position"))
    ox, oy = op if op is not None else (sx, sy)

    grid_w = observation.get("grid_width", 0) or 0
    grid_h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            if op is not None:
                return clamp_move(sgn(ox - sx), sgn(oy - sy))
            return [0, 0]
        corners = []
        if grid_w and grid_h:
            corners = [(0, 0), (0, grid_h - 1), (grid_w - 1, 0), (grid_w - 1, grid_h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = None
        best_d = None
        for c in corners:
            d = abs(c[0] - ox) + abs(c[1] - oy)
            if best_d is None or d > best_d:
                target = c
                best_d = d
        return clamp_move(sgn(target[0] - sx), sgn(target[1] - sy))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = nearest(targets, sx, sy)
        if target is None:
            target = pos(observation.get("goal_position")) or op
        if target is None:
            return [0, 0]
        return clamp_move(sgn(target[0] - sx), sgn(target[1] - sy))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = nearest(resources, sx, sy)

    if target is not None:
        return clamp_move(sgn(target[0] - sx), sgn(target[1] - sy))

    if op is not None:
        # Default: pursue if nothing else is visible.
        return clamp_move(sgn(ox - sx), sgn(oy - sy))

    # Last resort: gentle diagonal drift to avoid stagnation.
    return [0, 1]

